66	// Policy tier constants for priority calculation
67	export const DEFAULT_POLICY_TIER = 1;
68	export const EXTENSION_POLICY_TIER = 2;
69	export const WORKSPACE_POLICY_TIER = 3;
70	export const USER_POLICY_TIER = 4;
71	export const ADMIN_POLICY_TIER = 5;
72	
73	// Specific priority offsets and derived priorities for dynamic/settings rules.
74	
75	export const MCP_EXCLUDED_PRIORITY = USER_POLICY_TIER + 0.9;
76	export const EXCLUDE_TOOLS_FLAG_PRIORITY = USER_POLICY_TIER + 0.4;
77	export const ALLOWED_TOOLS_FLAG_PRIORITY = USER_POLICY_TIER + 0.3;
78	export const TRUSTED_MCP_SERVER_PRIORITY = USER_POLICY_TIER + 0.2;
79	export const ALLOWED_MCP_SERVER_PRIORITY = USER_POLICY_TIER + 0.1;
