81	// These are added to the tier base (e.g., USER_POLICY_TIER).
82	// Workspace tier (3) + high priority (950/1000) = ALWAYS_ALLOW_PRIORITY
83	export const ALWAYS_ALLOW_PRIORITY =
84	  WORKSPACE_POLICY_TIER + ALWAYS_ALLOW_PRIORITY_OFFSET;
