86	/**
87	 * Returns the fractional priority of ALWAYS_ALLOW_PRIORITY scaled to 1000.
88	 */
89	export function getAlwaysAllowPriorityFraction(): number {
90	  return Math.round((ALWAYS_ALLOW_PRIORITY % 1) * 1000);
91	}
