93	/**
94	 * Gets the list of directories to search for policy files, in order of increasing priority
95	 * (Default -> Extension -> Workspace -> User -> Admin).
96	 *
97	 * Note: Extension policies are loaded separately by the extension manager.
98	 *
99	 * @param defaultPoliciesDir Optional path to a directory containing default policies.
100	 * @param policyPaths Optional user-provided policy paths (from --policy flag).
101	 *   When provided, these replace the default user policies directory.
102	 * @param workspacePoliciesDir Optional path to a directory containing workspace policies.
103	 * @param adminPolicyPaths Optional admin-provided policy paths (from --admin-policy flag).
104	 *   When provided, these supplement the default system policies directory.
105	 */
106	export function getPolicyDirectories(
107	  defaultPoliciesDir?: string,
108	  policyPaths?: string[],
109	  workspacePoliciesDir?: string,
110	  adminPolicyPaths?: string[],
111	): string[] {
112	  return [
113	    // Admin tier (highest priority)
114	    Storage.getSystemPoliciesDir(),
115	    ...(adminPolicyPaths ?? []),
116	
117	    // User tier (second highest priority)
118	    ...(policyPaths && policyPaths.length > 0
119	      ? policyPaths
120	      : [Storage.getUserPoliciesDir()]),
121	
122	    // Workspace Tier (third highest)
123	    workspacePoliciesDir,
124	
125	    // Default tier (lowest priority)
126	    defaultPoliciesDir ?? DEFAULT_CORE_POLICIES_DIR,
127	  ].filter((dir): dir is string => !!dir);
128	}
129	
130	/**
131	 * Determines the policy tier (1=default, 2=extension, 3=workspace, 4=user, 5=admin) for a given directory.
132	 * This is used by the TOML loader to assign priority bands.
133	 */
134	export function getPolicyTier(
135	  dir: string,
136	  context: {
137	    defaultPoliciesDir?: string;
138	    workspacePoliciesDir?: string;
139	    adminPolicyPaths?: Set<string>;
140	    systemPoliciesDir: string;
141	    userPoliciesDir: string;
142	  },
143	): number {
144	  const normalizedDir = path.resolve(dir);
145	
146	  if (normalizedDir === context.systemPoliciesDir) {
147	    return ADMIN_POLICY_TIER;
148	  }
149	  if (context.adminPolicyPaths?.has(normalizedDir)) {
150	    return ADMIN_POLICY_TIER;
151	  }
152	  if (normalizedDir === context.userPoliciesDir) {
153	    return USER_POLICY_TIER;
154	  }
155	  if (
156	    context.workspacePoliciesDir &&
157	    normalizedDir === path.resolve(context.workspacePoliciesDir)
158	  ) {
159	    return WORKSPACE_POLICY_TIER;
160	  }
161	  if (
162	    context.defaultPoliciesDir &&
163	    normalizedDir === path.resolve(context.defaultPoliciesDir)
164	  ) {
165	    return DEFAULT_POLICY_TIER;
166	  }
167	  if (normalizedDir === path.resolve(DEFAULT_CORE_POLICIES_DIR)) {
168	    return DEFAULT_POLICY_TIER;
169	  }
170	
171	  return DEFAULT_POLICY_TIER;
172	}
